                  labelPlacement="floating"
                  type="number"
                  value={formState.completionTokens}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, completionTokens: parseInt(e.detail.value!, 10) }))}
                  required
                />
              </div>
              <div className="factoryrunusage-field-group">
                <IonInput
                  fill="outline"
                  label="Total de Tokens *"
                  labelPlacement="floating"
                  type="number"
                  value={formState.totalTokens}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, totalTokens: parseInt(e.detail.value!, 10) }))}
                  required
                />
              </div>
              <div className="factoryrunusage-field-group">
                <IonInput
                  fill="outline"
                  label="Costo (USD) *"
                  labelPlacement="floating"
                  type="number"
                  step="0.01"
                  value={formState.costUSD}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, costUSD: parseFloat(e.detail.value!) }))}
                  required
                />
              </div>
              <div className="factoryrunusage-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre del Modelo *"
                  labelPlacement="floating"
                  value={formState.modelName}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, modelName: e.detail.value! }))}
                  required
                />
              </div>
              <div className="factoryrunusage-field-group">
                <IonItem fill="outline" className="datetime-item">
                  <IonLabel position="floating">Timestamp *</IonLabel>
                  <IonDatetimeButton datetime="timestamp-datetime"></IonDatetimeButton>
                  <IonModal keepContentsMounted={true}>
                    <IonDatetime
                      id="timestamp-datetime"
                      value={formState.timestamp}
                      onIonChange={(e: CustomEvent<DatetimeChangeEventDetail>) => setFormState(p => ({ ...p, timestamp: e.detail.value as string }))}
                    />
                  </IonModal>
                </IonItem>
              </div>
              <IonButton expand="block" type="submit" className="ion-margin-top" disabled={saving}>
                {saving ? 'Guardando...' : 'Guardar'}
              </IonButton>
            </form>
          </IonContent>
        </IonModal>
      </IonContent>
    </IonPage>
  );
};

export default FactoryRunUsagePage;
